"""Build original, script-free marketing HTML. No account/billing implementation or secrets."""
from pathlib import Path
import json,html,shutil
ROOT=Path(__file__).resolve().parent
SOURCE=ROOT.parent/'website-overlay'
if not SOURCE.exists(): SOURCE=ROOT.parent/'pixa-website-overlay'
data=(SOURCE/'lib/pixa-products.ts').read_text().split('export const products: PixaProduct[] = ',1)[1]
products=json.loads(data.strip().rstrip(';'))
OUT=ROOT/'public';OUT.mkdir(exist_ok=True)
assets=OUT/'pixa-showcase';assets.mkdir(exist_ok=True)
shutil.copytree(SOURCE/'public/pixa-icons',assets/'icons',dirs_exist_ok=True)
(assets/'catalog.css').write_text((SOURCE/'components/pixa/catalog.module.css').read_text()+'\nhtml,body{margin:0;padding:0;background:#0b101a}body{font-family:Arial,sans-serif}.site button{font:inherit}.site button:disabled{opacity:.85;cursor:default}a,button{-webkit-tap-highlight-color:transparent}img{max-width:100%;height:auto}.site button.pending{background:transparent}\n')
def e(value):return html.escape(value,quote=True)
def icon(p,size=72):return f'<img src="/pixa-showcase/icons/{p["id"]}.svg" width="{size}" height="{size}" alt="" decoding="async">'
def shell(title,description,body,path='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b101a"><title>{e(title)} | Pixa by AIWebDesignFirm</title><meta name="description" content="{e(description)}"><link rel="canonical" href="https://aiwebdesignfirm.com{e(path)}"><link rel="stylesheet" href="/pixa-showcase/catalog.css"></head><body><div class="site"><a class="skip" href="#main-content">Skip to content</a><header class="nav"><a class="wordmark" href="/">Pixa<span>by AIWebDesignFirm</span></a><nav aria-label="Main navigation"><a href="/products">All apps</a><a href="/launcher">Launcher</a><a href="https://aiwebdesignfirm.com/settings">Your account →</a></nav></header><main id="main-content">{body}</main><footer class="footer"><a href="/products">The Pixa app family</a><p>by AIWebDesignFirm</p><div><a href="https://aiwebdesignfirm.com/pixashop/manual">PixaShop help</a><a href="https://aiwebdesignfirm.com/settings">Account &amp; billing</a></div></footer></div></body></html>'''

progress=json.loads((ROOT/'progress.json').read_text())
def progress_panel(pid):
 rows=progress['apps'][pid]
 items=''.join('<li><span class="statusLight '+('passed' if r['passed'] else 'pendingLight')+'" aria-hidden="true"></span><div><strong>'+e(r['label'])+'</strong><small>'+('Passed' if r['passed'] else 'Pending / unverified')+' — '+e(r['note'])+'</small></div></li>' for r in rows)
 return '<details class="buildProgress"><summary>Build progress <span>'+str(sum(r['passed'] for r in rows))+'/7 verified</span></summary><ol>'+items+'</ol><p>Last checked: '+e(progress['verified_at'][:10])+'. Green: passed. Red: pending or unverified.</p></details>'

def grid():
 cards=[]
 for p in products:
  status='See download availability' if p['id']=='pixashop' else 'Coming soon'
  cards.append(f'<article class="card"><a class="cardLink" href="/products/{p["id"]}">{icon(p)}<p class="category">{e(p["category"])}</p><h3>{e(p["name"])}<span aria-hidden="true">→</span></h3><p>{e(p["summary"])}</p><div class="cardFoot"><span>{status}</span><span aria-hidden="true">Explore →</span></div></a>{progress_panel(p["id"])}</article>')
 return '<section class="section" id="products" aria-labelledby="catalog-heading"><div class="sectionHead"><div><p class="eyebrow">FIND YOUR WORKSPACE</p><h2 id="catalog-heading">One family. Every kind of idea.</h2></div><p>Discover the Pixa apps. Each product page shows its current download status.</p></div><div class="grid">'+''.join(cards)+'</div></section>'
home='<section class="hero"><p class="eyebrow">THE PIXA APP FAMILY</p><h1>Your ideas.<br><span>The tools to shape them.</span></h1><p class="lead">From the first pixel to the final frame. Discover focused desktop workspaces for the things you want to make.</p><div class="actions"><a class="primary" href="#products">Explore the apps <span aria-hidden="true">↓</span></a><a class="secondary" href="https://aiwebdesignfirm.com/pixashop">PixaShop downloads →</a></div><p class="note">Sixteen individual apps. More workspaces coming soon.</p></section>'+grid()+'<section class="launcher"><div><p class="eyebrow">THE NEXT CHAPTER</p><h2>Your apps. One starting point.</h2><p>A Pixa launcher is planned to bring the family together. Explore the individual apps while it takes shape.</p><a href="/launcher">About the launcher →</a></div><div class="launcherStatus"><strong>Launcher coming soon</strong><p>A verified installer will be listed when the launcher is ready.</p></div></section>'
(OUT/'index.html').write_text(shell('Your ideas. The tools to shape them.','Explore the Pixa creative app family: images, video, design, audio and documents.',home))
(OUT/'products.html').write_text(shell('All Pixa apps','Explore all sixteen Pixa apps and their current download availability.','<section class="hero"><p class="eyebrow">THE COMPLETE FAMILY</p><h1>A workspace<br><span>for every idea.</span></h1><p class="lead">Images, films, layouts, documents, sound. Find the app built around your kind of work.</p></section>'+grid(),'/products'))
(OUT/'products').mkdir(exist_ok=True)
for p in products:
 available=p['id']=='pixashop'
 features=''.join(f'<article><h3>{e(title)}</h3><p>{e(copy)}</p></article>' for title,copy in p['capabilities'])
 action='<a class="primary" href="https://aiwebdesignfirm.com/pixashop">Open PixaShop downloads →</a>' if available else '<button class="pending" type="button" disabled>Coming soon</button>'
 text='Choose an available installer on the existing PixaShop download page. Your account and access requirements apply.' if available else 'The Pixa edition is being prepared for release. A verified installer will be available here when it is ready.'
 platforms=''.join('<div><strong>'+platform+'</strong><span>'+('Check download page' if available else 'Coming soon')+'</span></div>' for platform in ('macOS','Windows','Linux'))
 body=f'<section class="detailHero"><div><a class="back" href="/products">← All Pixa apps</a><p class="eyebrow">{e(p["category"])}</p><h1>{e(p["name"])}<span class="dot">.</span></h1><p class="lead">{e(p["summary"])}</p><p class="description">{e(p["description"])}</p><a class="primary" href="#downloads">'+('Find your download' if available else 'View release status')+f' ↓</a></div><div class="heroIcon">{icon(p,240)}</div></section><section class="section"><p class="eyebrow">THE WORKSPACE</p><h2>Made for {e(p["use"])}.</h2><div class="features">{features}</div></section><section class="download" id="downloads"><div><p class="eyebrow">{e(p["name"].upper())}</p><h2>'+('Your next project starts here.' if available else 'Coming soon.')+f'</h2><p>{text}</p>{action}</div><div class="platforms" aria-label="Platform availability">{platforms}</div></section><section class="more"><p>Explore the rest of your creative toolkit.</p><a href="/products">Browse all apps →</a></section>'
 (OUT/'products'/(p['id']+'.html')).write_text(shell(p['name']+' — '+p['category'],p['summary'],body,'/products/'+p['id']))
launcher='<section class="hero"><p class="eyebrow">PIXA LAUNCHER</p><h1>One place.<br><span>Your whole toolkit.</span></h1><p class="lead">The planned starting point for discovering, installing and opening your Pixa apps.</p><button class="pending" type="button" disabled>Coming soon</button><p class="note">A launcher installer is not available yet.</p></section><section class="section"><p class="eyebrow">THE DIRECTION</p><h2>A simpler way into your work.</h2><div class="features"><article><h3>Discover your apps</h3><p>A clear library of Pixa workspaces, planned for one home.</p></article><article><h3>Install what you need</h3><p>Individual app installation is planned, without downloading the whole family.</p></article><article><h3>Keep moving forward</h3><p>A verified update and restart flow is planned for future releases.</p></article></div></section><section class="more"><p>Explore the individual products now.</p><a href="/products">Browse all apps →</a></section>'
(OUT/'launcher.html').write_text(shell('Pixa Launcher — Coming soon','The planned home for your Pixa apps. Launcher download coming soon.',launcher,'/launcher'))
(OUT/'404.html').write_text(shell('Page not found','Explore the Pixa app family.','<section class="hero"><p class="eyebrow">PAGE NOT FOUND</p><h1>Find your next idea.</h1><a class="primary" href="/products">Browse all apps →</a></section>'))
(ROOT/'vercel.json').write_text(json.dumps({'cleanUrls':True,'trailingSlash':False,'headers':[{'source':'/pixa-showcase/(.*)','headers':[{'key':'Cache-Control','value':'public, max-age=3600'}]}]},indent=2)+'\n')
(assets/'catalog.css').write_text((assets/'catalog.css').read_text()+"\n.cardLink{display:block;color:inherit;text-decoration:none}.buildProgress{margin-top:18px;border-top:1px solid #30394a;padding-top:14px}.buildProgress summary{cursor:pointer;font-size:13px;font-weight:600}.buildProgress summary span{float:right;color:#9ca9bc;font-size:11px}.buildProgress ol{list-style:none;margin:16px 0;padding:0}.buildProgress li{display:flex;gap:9px;margin:13px 0;align-items:flex-start}.statusLight{width:9px;height:9px;min-width:9px;border-radius:50%;margin-top:5px}.passed{background:#45dc8b;box-shadow:0 0 7px #45dc8b66}.pendingLight{background:#ff616d;box-shadow:0 0 7px #ff616d44}.buildProgress strong{font-size:12px;line-height:1.5}.buildProgress small{display:block;color:#a4afc0;font-size:11px;line-height:1.6;margin-top:3px}.buildProgress>p{font-size:10px!important;line-height:1.6;color:#9ba7ba}.card:has(details[open]){align-self:start}\n")
print('Built script-free showcase: 16 product pages, catalog, launcher and original assets')
